// Anúncio UDP de um Slave (o mesmo JSON do /status, versão curta).
let a;
try { a = JSON.parse(msg.payload); } catch (e) { return null; }
if (!a || typeof a.id !== 'string' || !a.id.startsWith('SLAVE-')) return null;
const mac = a.id.slice(6).replace(/:/g, '').toUpperCase();
const curto = mac.slice(-6);
const agora = Date.now();

const estado = {
  nome: a.nome, ip: a.ip || msg.ip, versao: a.versao, rssi: a.rssi,
  temperatura: a.temperatura, umidade: a.umidade,
  arLigado: a.arLigado, setpoint: a.setpoint, modo: a.modoOperacao, ventilacao: a.ventilacaoOperacao,
  presenca: !!a.radarPresenca, presencaContinuaS: a.presencaContinuaS,
  presRadar: a.presRadar, distRadar: a.distRadar, presExtra: a.presExtra, distExtra: a.distExtra,
  radar: a.radarDisponivel, automacao: a.statusAutomacao, reivindicado: a.reivindicado
};

const slaves = flow.get('slaves') || {};
const antes = slaves[mac];
// A placa do Master virou Slave (mesmo MAC): herda o nome da sala, sai o ambiente
// "do Master" e as mensagens retidas antigas dele são apagadas (senão sobra uma
// sala fantasma no painel e no assistente de voz).
const aposentar = [];
const idMaster = 'MASTER-' + mac.match(/../g).join(':');
const chaveVelha = Object.keys(slaves).find((k) => slaves[k].viaMaster && (slaves[k].bruto || {}).id === idMaster);
if (chaveVelha) {
  const velho = slaves[chaveVelha];
  const nomes = flow.get('nomes') || {};
  if (!nomes[mac] && velho.bruto && velho.bruto.nome) { nomes[mac] = velho.bruto.nome; flow.set('nomes', nomes); }
  const base = velho.viaMaster.topico.split('/').slice(0, 2).join('/');
  aposentar.push({ topic: velho.viaMaster.topico.replace(/\/set$/, ''), payload: '', retain: true });
  for (const k of Object.keys(slaves)) if (slaves[k].bruto && slaves[k].bruto.id && !slaves[k].viaMaster)
    aposentar.push({ topic: base + '/ambiente/' + slaves[k].bruto.id, payload: '', retain: true });
  aposentar.push({ topic: base + '/seguranca', payload: '', retain: true }, { topic: base + '/status', payload: 'offline', retain: true });
  delete slaves[chaveVelha];
  flow.set('mastersAposentados', Object.assign(flow.get('mastersAposentados') || {}, { [mac]: Date.now() }));
}
const viaMqtt = String(msg.topic || '').endsWith('/anuncio');
slaves[mac] = { estado, bruto: a, visto: agora, publicado: antes ? antes.publicado : 0,
                anunciado: antes ? antes.anunciado : false, online: true,
                mqttVisto: viaMqtt ? agora : (antes ? antes.mqttVisto || 0 : 0) };
flow.set('slaves', slaves);

const saida = [];
const base = 'accontrol/slave/' + mac;
// Publica quando muda ou a cada 60 s (os anúncios chegam a cada poucos segundos).
const mudou = !antes || JSON.stringify(antes.estado) !== JSON.stringify(estado);
if (mudou || agora - slaves[mac].publicado > 60000) {
  slaves[mac].publicado = agora;
  saida.push({ topic: base + '/estado', payload: Object.assign({ recebidoEm: new Date(agora).toISOString() }, estado), retain: true });
}
if (!antes || !antes.online) saida.push({ topic: base + '/online', payload: 'online', retain: true });

// Descoberta do Home Assistant, uma vez por Slave (retida no broker).
if (!slaves[mac].anunciado) {
  slaves[mac].anunciado = true;
  const disp = { identifiers: ['accontrol_' + mac], name: 'AC Control ' + curto,
                 manufacturer: 'THR Control', model: 'Slave', sw_version: a.versao };
  const comum = (chave, nome) => ({ name: nome, unique_id: 'accontrol_' + mac + '_' + chave,
    state_topic: base + '/estado', availability_topic: base + '/online', device: disp });
  const sensores = [
    ['sensor', 'temperatura', Object.assign(comum('temperatura', 'Temperatura'), { device_class: 'temperature', unit_of_measurement: '°C', value_template: '{{ value_json.temperatura }}' })],
    ['sensor', 'umidade', Object.assign(comum('umidade', 'Umidade'), { device_class: 'humidity', unit_of_measurement: '%', value_template: '{{ value_json.umidade }}' })],
    ['binary_sensor', 'presenca', Object.assign(comum('presenca', 'Presença'), { device_class: 'occupancy', value_template: "{{ 'ON' if value_json.presenca else 'OFF' }}" })],
    ['binary_sensor', 'ar', Object.assign(comum('ar', 'Ar-condicionado ligado'), { device_class: 'power', value_template: "{{ 'ON' if value_json.arLigado else 'OFF' }}" })],
    ['sensor', 'setpoint', Object.assign(comum('setpoint', 'Temperatura programada'), { unit_of_measurement: '°C', value_template: '{{ value_json.setpoint }}' })],
    ['sensor', 'rssi', Object.assign(comum('rssi', 'Sinal Wi-Fi'), { device_class: 'signal_strength', unit_of_measurement: 'dBm', entity_category: 'diagnostic', value_template: '{{ value_json.rssi }}' })]
  ];
  for (const [tipo, chave, cfg] of sensores)
    saida.push({ topic: 'homeassistant/' + tipo + '/accontrol_' + mac + '/' + chave + '/config', payload: cfg, retain: true });
  flow.set('slaves', slaves);
}
// Feriados locais: o Slave (firmware novo) diz a lista que tem; se for diferente
// da do hub, o hub manda de novo (no máximo a cada 30 s por Slave).
const segCfg = flow.get('segCfg');
if (viaMqtt && segCfg && typeof a.feriadosLocais === 'string') {
  const desejada = (segCfg.feriadosLocais || []).map((f) => f.data).join(',');
  const enviados = flow.get('feriadosEnviados') || {};
  if (a.feriadosLocais !== desejada && agora - (enviados[mac] || 0) > 30000) {
    enviados[mac] = agora; flow.set('feriadosEnviados', enviados);
    saida.push({ topic: base + '/set', payload: { acao: 'feriados', lista: desejada } });
  }
}
node.status({ fill: 'green', shape: 'dot', text: Object.keys(slaves).length + ' Slave(s) · último ' + curto });
return [saida.concat(aposentar)];

// A cada 30 s: Slave sem anúncio há 90 s fica "offline".
const slaves = flow.get('slaves') || {};
const agora = Date.now();
const saida = [];
for (const mac of Object.keys(slaves)) {
  const s = slaves[mac];
  if (s.online && agora - s.visto > (s.viaMaster ? 660000 : 90000)) {
    s.online = false;
    if (!s.viaMaster) saida.push({ topic: 'accontrol/slave/' + mac + '/online', payload: 'offline', retain: true });
  }
}
flow.set('slaves', slaves);
return [saida];

// Manda o comando ao Slave de teste (variável TESTE_MAC da aba).
const mac = String(env.get('TESTE_MAC') || '').replace(/:/g, '').toUpperCase();
if (!mac) { node.warn('Defina TESTE_MAC nas variáveis da aba'); return null; }
msg.topic = 'accontrol/slave/' + mac + '/set';
node.status({ text: msg.payload.acao + ' ' + (msg.payload.valor || '') + ' → ' + mac.slice(-6) });
return msg;

// GET /accontrol/slaves: o que o hub está ouvindo (para conferir).
const slaves = flow.get('slaves') || {};
const agora = Date.now();
msg.payload = Object.keys(slaves).sort().map((mac) => Object.assign(
  { mac, online: slaves[mac].online, vistoHaSegundos: Math.round((agora - slaves[mac].visto) / 1000) },
  slaves[mac].estado));
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

