.zigbee-lista{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px}
.luz,.cortina{padding:14px;border-radius:16px;background:var(--card);border:1px solid var(--card-borda)}
.luz{display:flex;justify-content:space-between;align-items:center;gap:10px}
.luz b,.cortina b{display:block;font-size:14px}
.luz span,.cortina span.sub{font-size:12px;color:var(--texto3)}
.luz .chave{background:var(--texto3);opacity:.5}
.luz .chave.on{background:var(--aviso);opacity:1}
.cortina{grid-column:span 2}
.cortina-topo{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.cortina-topo strong{font-size:20px}
.cortina input[type=range]{padding:0;border:0;background:none;box-shadow:none;accent-color:var(--acento);margin:10px 0 8px}
.cortina-botoes{display:flex;gap:6px}
.cortina-botoes button{flex:1;padding:8px;border-radius:10px;font-weight:700;font-size:13px;background:var(--campo);
border:1px solid var(--campo-borda);color:var(--texto)}
.zigbee button:disabled{opacity:.4;cursor:not-allowed}
@media (max-width:520px){.cortina{grid-column:auto}}
@media (max-width:768px){.heroi{grid-template-columns:minmax(0,1fr);justify-items:center;text-align:center}.heroi-info{width:100%}.liga{justify-content:center}.faixa{grid-template-columns:minmax(0,1fr)}}
