</main></div><div class="toast" id="toast"></div><script>
let falhas = 0, ultimaAtualizacao = 0;
// Opção liga/desliga e campo de formulário (Automações e Segurança).
function opcao(classe, marcado, titulo, detalhe) {
  return '<label class="opcao"><span>' + titulo + (detalhe ? '<small>' + detalhe + '</small>' : '') + '</span>' +
    '<input type="checkbox" class="chk ' + classe + '"' + (marcado ? ' checked' : '') + '></label>';
}
function campo(classe, rotulo, tipo, valor, extra) {
  return '<label>' + rotulo + '<input class="' + classe + '" type="' + tipo + '" value="' + esc(valor) + '" ' + (extra || '') + '></label>';
}
function esc(t) {
  return String(t == null ? '' : t).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function numero(v, casas) { return Number(v).toFixed(casas).replace('.', ','); }
function temValor(v) { return v !== null && v !== undefined && v !== '' && !isNaN(v); }
function aviso(texto, erro) {
  const t = document.getElementById('toast');
  t.textContent = texto;
  t.className = 'toast visivel' + (erro ? ' erro' : '');
  clearTimeout(aviso.timer);
  aviso.timer = setTimeout(() => { t.className = 'toast' + (erro ? ' erro' : ''); }, erro ? 4000 : 1800);
}
async function postar(rota) {
  const r = await fetch(rota, { method: 'POST', cache: 'no-store' });
  if (r.status === 401) { location.href = '/login'; throw new Error('Sessão expirada'); }
  if (!r.ok) {
    let detalhe = 'Erro HTTP ' + r.status;
    try { const j = await r.json(); if (j.erro) detalhe = j.erro; } catch (_) { }
    throw new Error(detalhe);
  }
  return r;
}
// Leituras uma de cada vez: cada resposta passa pelos buffers de Wi-Fi da
// RAM interna do Master, e várias juntas eram os picos de memória (ver
// MUDANCAS, "Medidas de memória"). A mesma rota já na fila não entra de novo.
let filaLeituras = Promise.resolve();
const leiturasNaFila = new Map();
function buscar(rota) {
  if (leiturasNaFila.has(rota)) return leiturasNaFila.get(rota);
  const vez = filaLeituras.then(async () => {
    // Sem resposta em 8 s: desiste, para uma leitura presa não parar a fila.
    const limite = new AbortController();
    const relogio = setTimeout(() => limite.abort(), 8000);
    try {
      const r = await fetch(rota + (rota.indexOf('?') < 0 ? '?' : '&') + 't=' + Date.now(), { cache: 'no-store', signal: limite.signal });
      if (r.status === 401) { location.href = '/login'; throw new Error('401'); }
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } finally { clearTimeout(relogio); leiturasNaFila.delete(rota); }
  });
  leiturasNaFila.set(rota, vez);
  filaLeituras = vez.catch(() => { });
  return vez;
}
function conexao(ok) {
  falhas = ok ? 0 : falhas + 1;
  const caiu = falhas >= 2;
  document.body.classList.toggle('desconectado', caiu);
  document.getElementById('estadoLateral').innerHTML = caiu
    ? '<span class="ponto off"></span><span style="color:var(--perigo)">Reconectando…</span>'
    : '<span class="ponto"></span><span style="color:var(--ok)">Hub online</span>';
  if (ok) ultimaAtualizacao = Date.now();
}
function segundosDesde() {
  return ultimaAtualizacao ? 'há ' + Math.round((Date.now() - ultimaAtualizacao) / 1000) + ' s' : '---';
}
document.getElementById('hostLateral').textContent = location.hostname;

const MIN_T = 16, MAX_T = 32, ARCO = 405.3;
const NOME_MODO = { frio: '❄ Frio', seco: '💧 Seco', ventilacao: '🌀 Ventilação' };
const NOME_VENT = { auto: 'automática', baixa: 'baixa', media: 'média', alta: 'alta' };
let nos = null, statusMaster = null, htmlAmbientes = '';
let selecionadoId = 'master';
try { selecionadoId = localStorage.getItem('ambienteSelecionado') || 'master'; } catch (_) { }
// Valor otimista de cada comando até o status confirmar (ou desistir em 10 s).
const pendentes = {};
// Um comando por vez por ambiente: o transmissor IR só manda um quadro por vez.
const filas = {};

function frase(t) { t = String(t || '').trim(); return t ? t.charAt(0) + t.slice(1).toLowerCase() : ''; }
function nomePerfil(p) {
  p = String(p || '').trim();
  return !p || p === '/' || p.startsWith('/') || /^nenhum/i.test(p) ? 'Nenhum' : p.replace(/\s*\/\s*$/, '');
}

function montarAmbientes() {
  if (!nos) return [];
  const m = nos.master, s = statusMaster || {};
  const lista = !m ? [] : [{
    id: 'master', papel: 'Master', nome: m.nome, ip: m.ip, online: true,
    temp: m.temperatura, umid: m.umidade, sensor: m.radarDisponivel, presenca: m.radarPresenca,
    ligado: s.arLigado !== undefined ? s.arLigado : m.arLigado,
    alvo: s.setpoint !== undefined ? s.setpoint : m.setpoint,
    modo: s.modoOperacao || 'frio', vent: s.ventilacaoOperacao || 'auto',
    perfil: nomePerfil(m.perfil), ultimo: s.ultimoComando,
    automacaoAtiva: m.automacaoAtiva, automacao: m.statusAutomacao
  }];
  (nos.escravos || []).forEach((e) => lista.push({
    id: e.id, papel: 'Slave', nome: e.nome, ip: e.ip, online: e.online,
    temp: e.temperatura, umid: e.umidade, sensor: e.online && e.radarDisponivel, presenca: e.radarPresenca,
    ligado: e.arLigado, alvo: e.setpoint, modo: e.modoOperacao || 'frio', vent: e.ventilacaoOperacao || 'auto',
    perfil: nomePerfil(e.perfil), ultimo: e.ultimoComando,
    automacaoAtiva: e.automacaoAtiva, automacao: e.statusAutomacao
  }));
  lista.forEach((a) => {
    const p = pendentes[a.id];
    if (!p) return;
    Object.keys(p).forEach((campo) => {
      if (Date.now() > p[campo].ate || a[campo] === p[campo].v) delete p[campo];
      else a[campo] = p[campo].v;
    });
  });
  return lista;
}

function faixaTemp(t) {
  if (t > 28) return ['perigo', 'Quente demais'];
  if (t > 26) return ['aviso', 'Um pouco quente'];
  if (t < 18) return ['frio', 'Frio demais'];
  if (t < 20) return ['frio', 'Um pouco frio'];
  return ['ok', 'Confortável'];
}
function faixaUmid(u) {
  if (u > 70) return ['perigo', 'Muito úmido'];
  if (u < 30) return ['perigo', 'Muito seco'];
  if (u > 60) return ['aviso', 'Um pouco úmido'];
  if (u < 40) return ['aviso', 'Um pouco seco'];
  return ['ok', 'Confortável'];
}
function definir(id, classe, html) {
  const el = document.getElementById(id);
  el.className = classe;
  el.innerHTML = html;
}

function ambienteSelecionado(lista) {
  return lista.find((a) => a.id === selecionadoId && a.online) || lista[0];
}

function desenhar() {
  const lista = montarAmbientes();
  if (!lista.length) return;
  const a = ambienteSelecionado(lista);
  const online = lista.filter((x) => x.online).length;
  document.getElementById('resumo').textContent =
    lista.length + (lista.length === 1 ? ' ambiente' : ' ambientes') + ' · ' + online + ' online';

  // Cartão principal
  document.getElementById('heroiRotulo').textContent = 'Ar-condicionado · ' + a.papel;
  document.getElementById('heroiNome').textContent = a.nome;
  document.getElementById('heroi').classList.toggle('desligado', !a.ligado);
  const fracao = a.ligado ? Math.max(0, Math.min(1, (a.alvo - MIN_T) / (MAX_T - MIN_T))) : 0;
  const arco = document.getElementById('arco');
  arco.setAttribute('stroke-dasharray', (fracao * ARCO) + ' 540.4');
  arco.setAttribute('stroke', a.modo === 'ventilacao' ? '#9be3c9' : a.modo === 'seco' ? '#ffd27a' : '#7cc4ff');
  document.getElementById('alvo').innerHTML = esc(a.alvo) + '<small>°C</small>';
  document.getElementById('legendaAnel').textContent = a.ligado ? 'temperatura programada' : 'ar desligado';
  let texto = '';
  if (!a.ligado) texto = 'Desligado. Toque na chave para ligar em ' + a.alvo + ' °C.';
  else if (a.modo === 'ventilacao') texto = 'Só ventilando, sem resfriar.';
  else if (a.modo === 'seco') texto = 'Desumidificando o ambiente.';
  else if (temValor(a.temp) && a.temp - a.alvo > 0.5)
    texto = 'Resfriando. A sala está ' + numero(a.temp - a.alvo, 1) + ' °C acima do programado.';
  else if (temValor(a.temp)) texto = 'Temperatura no ponto programado.';
  document.getElementById('frase').textContent = texto;
  document.getElementById('chaveAr').classList.toggle('on', !!a.ligado);
  document.getElementById('textoAr').textContent = a.ligado ? 'Ligado' : 'Desligado';
  document.querySelectorAll('.segmentos').forEach((g) => {
    g.querySelectorAll('button').forEach((b) => b.classList.toggle('ativo', b.dataset.v === a[g.dataset.campo]));
  });
  document.getElementById('textoAuto').textContent = a.automacaoAtiva
    ? 'Automação ativa' + (a.automacao ? ' · ' + frase(a.automacao) : '')
    : 'Automação desativada';
  document.getElementById('pontoAuto').classList.toggle('off', !a.automacaoAtiva);

  // Leituras
  if (temValor(a.temp)) {
    const f = faixaTemp(a.temp);
    definir('tempValor', 'leitura-valor t-' + f[0], numero(a.temp, 1) + '<small> °C</small>');
    definir('tempSelo', 'selo ' + f[0], f[1]);
  } else {
    definir('tempValor', 'leitura-valor', '--');
    definir('tempSelo', 'selo neutro', 'sem leitura');
  }
  if (temValor(a.umid)) {
    const f = faixaUmid(a.umid);
    definir('umidValor', 'leitura-valor t-' + (f[0] === 'ok' ? 'frio' : f[0]), Math.round(a.umid) + '<small> %</small>');
    definir('umidSelo', 'selo ' + f[0], f[1]);
  } else {
    definir('umidValor', 'leitura-valor', '--');
    definir('umidSelo', 'selo neutro', 'sem leitura');
  }
  if (!a.sensor) {
    definir('presValor', 'leitura-valor', 'Sem sensor');
    definir('presSelo', 'selo neutro', 'radar indisponível');
  } else if (a.presenca) {
    definir('presValor', 'leitura-valor t-ok', 'Ocupado');
    definir('presSelo', 'selo ok', 'presença confirmada');
  } else {
    definir('presValor', 'leitura-valor', 'Vazio');
    definir('presSelo', 'selo aviso', 'ninguém detectado');
  }

  // Lista de ambientes (só reconstrói se mudou, pra não engolir cliques)
  const html = lista.map((x) => {
    if (!x.online)
      return '<article class="cartao amb offline">' +
        '<div class="amb-topo"><div><b>' + esc(x.nome) + '</b><div class="sub">' + x.papel + ' · ' + esc(x.ip) + '</div></div>' +
        '<span class="selo perigo"><span class="ponto off"></span>Offline</span></div>' +
        '<div class="amb-meio"><div class="amb-temp">--<small>°C</small></div><div class="amb-alvo">alvo<b>-- °C</b></div></div>' +
        '<div class="amb-rodape"><span class="selo neutro">sem comunicação</span></div></article>';
    return '<article class="cartao amb' + (x.id === a.id ? ' selecionado' : '') + '" data-id="' + esc(x.id) + '">' +
      '<div class="amb-topo"><div><b>' + esc(x.nome) + '</b><div class="sub">' + x.papel +
      (x.papel === 'Slave' ? ' · ' + esc(x.ip) : '') + '</div></div>' +
      '<span class="selo ok"><span class="ponto"></span>Online</span></div>' +
      '<div class="amb-meio"><div class="amb-temp">' + (temValor(x.temp) ? numero(x.temp, 1) : '--') + '<small>°C</small></div>' +
      '<div class="amb-alvo">' + (x.ligado ? 'alvo<b>' + esc(x.alvo) + ' °C</b>' : 'ar<b>desligado</b>') + '</div></div>' +
      '<div class="amb-rodape">' + (x.ligado ? '<span class="selo frio">' + (NOME_MODO[x.modo] || esc(x.modo)) + '</span>' : '') +
      (x.sensor ? '<span class="selo ' + (x.presenca ? 'ok">Ocupado' : 'aviso">Vazio') + '</span>' : '<span class="selo neutro">sem radar</span>') +
      (luzesAcesas(x.id) ? '<span class="selo aviso">💡 ' + luzesAcesas(x.id) + '</span>' : '') +
      '<button class="chave' + (x.ligado ? ' on' : '') + '" data-ligar="' + esc(x.id) + '" aria-label="Ligar ou desligar"></button>' +
      '</div></article>';
  }).join('');
  if (html !== htmlAmbientes) {
    htmlAmbientes = html;
    document.getElementById('ambientes').innerHTML = html;
  }

  document.getElementById('perfil').textContent = a.perfil;
  document.getElementById('ultimo').textContent = a.ultimo || 'Nenhum';
