function rotaComando(a, campo, valor, delta) {
  if (a.id === 'master') {
    if (campo === 'ligado') return valor ? '/ligar' : '/off';
    if (campo === 'modo') return '/modo/' + valor;
    if (campo === 'vent') return '/ventilador/' + valor;
    return delta > 0 ? '/temperatura/mais' : '/temperatura/menos';
  }
  const comando = { ligado: valor ? 'on' : 'off', alvo: 'temp', modo: 'mode', vent: 'fan' }[campo];
  return '/escravo/comando?' + new URLSearchParams({
    id: a.id, comando: comando, valor: campo === 'ligado' ? '' : String(valor)
  }).toString();
}

function enviar(a, campo, valor, delta, descricao) {
  if (!pendentes[a.id]) pendentes[a.id] = {};
  pendentes[a.id][campo] = { v: valor, ate: Date.now() + 10000 };
  desenhar();
  const rota = rotaComando(a, campo, valor, delta);
  const anterior = filas[a.id] || Promise.resolve();
  const atual = anterior.catch(() => { }).then(() => postar(rota)).then(() => {
    aviso(a.nome + ' · ' + descricao + ' ✓');
  }).catch((e) => {
    if (pendentes[a.id]) delete pendentes[a.id][campo];
    aviso(e.message || 'Não foi possível enviar o comando', true);
    desenhar();
  });
  filas[a.id] = atual;
}

function atual() { const lista = montarAmbientes(); return lista.length ? ambienteSelecionado(lista) : null; }

function ajustar(d) {
  const a = atual();
  if (!a) return;
  const novo = Math.max(MIN_T, Math.min(MAX_T, Number(a.alvo) + d));
  if (novo === Number(a.alvo)) return;
  enviar(a, 'alvo', novo, d, novo + ' °C');
}
function ligarDesligar(id) {
  const lista = montarAmbientes();
  const a = id ? lista.find((x) => x.id === id) : ambienteSelecionado(lista);
  if (!a) return;
