</style></head><body><div class="blob b1"></div><div class="blob b2"></div><div class="blob b3"></div><div class="app"><aside class="lateral"><div class="marca"><div class="marca-icone"><svg width="40" height="40" viewBox="0 0 48 48" aria-label="THR"><g fill="currentColor"><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(0 24 24)"/><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(90 24 24)"/><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(135 24 24)"/><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(180 24 24)"/><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(225 24 24)"/><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(270 24 24)"/><rect x="20.5" y="3" width="7" height="9" rx="1.6" transform="rotate(315 24 24)"/></g><circle cx="24" cy="24" r="12" fill="none" stroke="currentColor" stroke-width="7" stroke-dasharray="66 9.4" transform="rotate(-25 24 24)"/><circle cx="35.6" cy="12.4" r="4.6" fill="#1fbfa8"/></svg></div><div><b>AC Control Pro</b><span>Painel do hub</span></div></div><nav class="nav"><a href="/"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 11l9-8 9 8v9a1 1 0 01-1 1h-5v-6H9v6H4a1 1 0 01-1-1z"/></svg>Controle</a><a href="/automacoes" class="ativo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>Automações</a><div class="subnav"><a href="/automacoes#ar" data-secao="ar">Ar-condicionado</a><a href="/automacoes#luzes" data-secao="luzes">Luzes</a><a href="/automacoes#feriados" data-secao="feriados">Feriados</a></div><a href="/seguranca"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l8 3v6c0 5-3.4 9.3-8 11-4.6-1.7-8-6-8-11V5z"/><path d="M8.5 12l2.5 2.5 4.5-5"/></svg>Segurança</a><a href="/relatorio"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg>Relatório</a><a href="/assistentes"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0014 0M12 17v4M8 21h8"/></svg>Assistentes de voz</a><a href="/configuracoes"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1"/></svg>Configurações</a></nav><div class="cartao dispositivo"><div style="font-size:13px;font-weight:700" id="estadoLateral"><span class="ponto"></span>Hub online</div><b style="display:block;margin:6px 0 2px">HUB · painel 3.0.3</b><div class="mono" style="font-size:12px;color:var(--texto3)"><span id="ipLateral"></span><br><span id="hostLateral"></span></div></div></aside><main class="conteudo"><div class="faixa-aviso" id="avisoConexao">● Reconectando ao hub… os valores abaixo podem estar desatualizados.</div>
<div class="topo"><div><h1>Automações</h1><p>Horário, temperaturas e presença de cada ambiente. As mudanças só valem depois de salvar.</p></div></div>
<div class="abas-auto" role="tablist"><button class="aba" type="button" role="tab" data-secao="ar">Ar-condicionado</button><button class="aba" type="button" role="tab" data-secao="luzes">Luzes</button><button class="aba" type="button" role="tab" data-secao="feriados">Feriados</button></div>
<div id="secAr"><div class="grade-auto" id="cartoes"><div class="cartao"><p class="desc" style="margin:0">Carregando automações…</p></div></div></div>
<div id="secLuzes" hidden><p class="desc" style="margin:0 0 14px;color:var(--texto2)">Apagar sem ninguém e acender ao chegar, pelo radar de cada ambiente.</p>
<div class="grade-auto" id="luzesCartoes"><div class="cartao"><p class="desc" style="margin:0">Carregando…</p></div></div></div>

<div id="secFeriados" hidden><p class="desc" style="margin:0 0 14px;color:var(--texto2)">Feriados estaduais e municipais. Neles a automação não liga o ar (como nos feriados nacionais, para quem tem "Bloquear feriados" ligado) e o alarme conta o dia como fechado.</p>
<div class="grade-auto">
<section class="cartao"><h3 style="margin:0 0 6px">Feriados locais</h3><div id="ferLista"><p class="desc" style="margin:0">Carregando…</p></div>
<div style="border-top:1px solid var(--card-borda);margin-top:14px;padding-top:14px">
<label for="ferData">Data</label><input id="ferData" type="date">
<label for="ferNome" style="margin-top:10px">Nome (opcional)</label><input id="ferNome" maxlength="40" placeholder="Ex.: Dia do Evangélico">
<label style="display:flex;gap:8px;align-items:center;margin-top:10px;font-weight:400"><input type="checkbox" id="ferAnual" checked style="width:auto"> Repete todo ano</label>
<button class="btn btn-principal" type="button" id="ferAdicionar" style="margin-top:12px">Adicionar</button></div></section>
<section class="cartao"><h3 style="margin:0 0 6px">Nos Slaves</h3><p class="desc">Cada Slave guarda a lista: vale mesmo com o hub fora do ar. O hub reenvia sozinho para quem estiver diferente.</p><div id="ferSlaves"></div>
<p class="desc" style="margin-top:12px">Nacionais (automáticos): 1/1, Sexta-feira Santa, 21/4, 1/5, 7/9, 12/10, 2/11, 15/11, 20/11 e 25/12.</p></section>
</div></div>
</main></div><div class="toast" id="toast"></div><script>
let falhas = 0, ultimaAtualizacao = 0;
// Opção liga/desliga e campo de formulário (Automações e Segurança).
function opcao(classe, marcado, titulo, detalhe) {
  return '<label class="opcao"><span>' + titulo + (detalhe ? '<small>' + detalhe + '</small>' : '') + '</span>' +
    '<input type="checkbox" class="chk ' + classe + '"' + (marcado ? ' checked' : '') + '></label>';
}
function campo(classe, rotulo, tipo, valor, extra) {
  return '<label>' + rotulo + '<input class="' + classe + '" type="' + tipo + '" value="' + esc(valor) + '" ' + (extra || '') + '></label>';
}
function esc(t) {
  return String(t == null ? '' : t).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function numero(v, casas) { return Number(v).toFixed(casas).replace('.', ','); }
function temValor(v) { return v !== null && v !== undefined && v !== '' && !isNaN(v); }
function aviso(texto, erro) {
  const t = document.getElementById('toast');
  t.textContent = texto;
  t.className = 'toast visivel' + (erro ? ' erro' : '');
  clearTimeout(aviso.timer);
  aviso.timer = setTimeout(() => { t.className = 'toast' + (erro ? ' erro' : ''); }, erro ? 4000 : 1800);
}
async function postar(rota) {
  const r = await fetch(rota, { method: 'POST', cache: 'no-store' });
  if (r.status === 401) { location.href = '/login'; throw new Error('Sessão expirada'); }
  if (!r.ok) {
    let detalhe = 'Erro HTTP ' + r.status;
    try { const j = await r.json(); if (j.erro) detalhe = j.erro; } catch (_) { }
    throw new Error(detalhe);
  }
  return r;
}
// Leituras uma de cada vez: cada resposta passa pelos buffers de Wi-Fi da
// RAM interna do Master, e várias juntas eram os picos de memória (ver
// MUDANCAS, "Medidas de memória"). A mesma rota já na fila não entra de novo.
let filaLeituras = Promise.resolve();
const leiturasNaFila = new Map();
function buscar(rota) {
  if (leiturasNaFila.has(rota)) return leiturasNaFila.get(rota);
  const vez = filaLeituras.then(async () => {
    // Sem resposta em 8 s: desiste, para uma leitura presa não parar a fila.
    const limite = new AbortController();
    const relogio = setTimeout(() => limite.abort(), 8000);
    try {
      const r = await fetch(rota + (rota.indexOf('?') < 0 ? '?' : '&') + 't=' + Date.now(), { cache: 'no-store', signal: limite.signal });
      if (r.status === 401) { location.href = '/login'; throw new Error('401'); }
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } finally { clearTimeout(relogio); leiturasNaFila.delete(rota); }
  });
  leiturasNaFila.set(rota, vez);
  filaLeituras = vez.catch(() => { });
  return vez;
}
function conexao(ok) {
  falhas = ok ? 0 : falhas + 1;
  const caiu = falhas >= 2;
  document.body.classList.toggle('desconectado', caiu);
  document.getElementById('estadoLateral').innerHTML = caiu
    ? '<span class="ponto off"></span><span style="color:var(--perigo)">Reconectando…</span>'
    : '<span class="ponto"></span><span style="color:var(--ok)">Hub online</span>';
  if (ok) ultimaAtualizacao = Date.now();
}
function segundosDesde() {
  return ultimaAtualizacao ? 'há ' + Math.round((Date.now() - ultimaAtualizacao) / 1000) + ' s' : '---';
}
document.getElementById('hostLateral').textContent = location.hostname;

const DIAS = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
// id -> { nome, online, cfg, alterado }
const ambientes = {};
let ordem = [];

function frase(t) { t = String(t || '').trim(); return t ? t.charAt(0) + t.slice(1).toLowerCase() : ''; }

function cartaoHTML(id) {
  const a = ambientes[id], c = a.cfg;
  const topo = '<div class="auto-topo"><div><h4>' + esc(a.nome) + '</h4><div class="sub">' + (id === 'master' ? 'Master' : 'Slave') + '</div></div>' +
    '<div class="auto-selos">' + (a.online && c
      ? '<span class="selo ok"><span class="ponto"></span>Online</span>' + (c.habilitada ? '<span class="selo ok">Ativa</span>' : '<span class="selo neutro">Desativada</span>')
      : '<span class="selo perigo"><span class="ponto off"></span>Sem comunicação</span>') + '</div></div>';
  if (!c)
    return '<section class="cartao" data-id="' + esc(id) + '">' + topo +
      '<p class="nota">Não foi possível ler a automação deste Slave agora. A página tenta de novo sozinha.</p></section>';
  let dias = '';
  for (let i = 0; i < 7; i++)
    dias += '<label class="dia"><input type="checkbox" class="d' + i + '"' + ((c.diasSemanaAtivos & (1 << i)) ? ' checked' : '') + '><span>' + DIAS[i] + '</span></label>';
  return '<section class="cartao' + (c.habilitada ? '' : ' desativado') + '" data-id="' + esc(id) + '">' + topo +
    '<div class="operacao">' + esc(frase(a.status || c.statusOperacao) || (c.habilitada ? 'Configurada' : 'Desativada')) + '</div>' +
    '<div class="principal-auto">' + opcao('habilitada', c.habilitada, 'Automação ativada', 'Liga, ajusta e desliga o ar sozinho dentro do horário.') + '</div>' +
    '<div class="bloco"><div class="rotulo">Horário e temperaturas</div><div class="campos">' +
      campo('inicio', 'Início', 'time', c.inicio) + campo('fim', 'Fim do expediente', 'time', c.fim) +
      campo('ausencia', 'Espera de ausência (min)', 'number', c.ausenciaMinutos, 'min="1" max="240"') +
      campo('conforto', 'Temperatura normal (°C)', 'number', c.temperaturaConforto, 'min="16" max="32"') +
      campo('economia', 'Temperatura econômica (°C)', 'number', c.temperaturaEconomia, 'min="16" max="32"') +
    '</div></div>' +
    '<div class="bloco"><div class="rotulo">Dias da semana</div><div class="dias">' + dias + '</div>' +
      '<p class="nota">Um dia desmarcado nunca liga o ar sozinho. Sábado e domingo, mesmo marcados, só ligam com presença confirmada.</p>' +
      opcao('bloquearFDS', c.bloquearFimDeSemana, 'Bloquear fim de semana', 'Não liga sábado e domingo nem com presença confirmada.') +
      (c.bloquearFeriados === undefined
        ? '<p class="nota">Atualize o firmware deste Slave para bloquear feriados.</p>'
        : opcao('bloquearFer', c.bloquearFeriados, 'Bloquear feriados nacionais', 'Não liga nos feriados nacionais (inclusive a Sexta-feira Santa) nem com presença confirmada.')) +
    '</div>' +
    '<div class="bloco"><div class="rotulo">Presença · ' + (c.presencaDisponivel ? 'sensor LD2410 disponível' : 'sensor indisponível') + '</div>' +
      opcao('soPresenca', c.ligarSomenteComPresenca, 'Ligar somente com presença') +
      opcao('desligaAusencia', c.desligarNaFaltaPresenca, 'Desligar na falta de presença') +
      opcao('desligaFim', c.desligarNoFim, 'Desligar ao fim do expediente') +
    '</div>' +
    '<div class="bloco"><div class="rotulo">Reforços</div>' +
      opcao('boost', c.boostVentiladorAtivo, 'Ventilador em ALTA se a sala esquentar demais', 'Volta à velocidade anterior quando a temperatura normalizar.') +
      '<div class="campos dois" style="margin:6px 0 8px">' + campo('boostC', 'Graus acima do programado', 'number', c.boostVentiladorLimiteC || 5, 'min="1" max="15"') + '</div>' +
      opcao('restaura', c.restaurarEstadoAposQueda, 'Reforçar o estado após queda de energia', 'Reenvia o último estado 2 min depois de a placa ligar.') +
    '</div>' +
    '<div class="rodape-auto"><button class="btn btn-principal" onclick="salvar(\'' + esc(id) + '\', this)">Salvar</button>' +
    '<span class="pendente">' + (a.alterado ? 'Alterações não salvas' : '') + '</span></div>' +
    '</section>';
}

function desenhar() {
  const raiz = document.getElementById('cartoes');
  ordem.forEach((id, i) => {
    let el = raiz.querySelector('[data-id="' + CSS.escape(id) + '"]');
    if (el && ambientes[id].alterado) return;
    const tmp = document.createElement('div');
    tmp.innerHTML = cartaoHTML(id);
    const novo = tmp.firstChild;
    if (el) { if (el.outerHTML !== novo.outerHTML) el.replaceWith(novo); }
    else raiz.appendChild(novo);
  });
  raiz.querySelectorAll('[data-id]').forEach((el) => { if (ordem.indexOf(el.dataset.id) < 0) el.remove(); });
  const carregando = raiz.querySelector('.cartao:not([data-id])');
  if (carregando && ordem.length) carregando.remove();
}

function lerCartao(el) {
  const q = (c) => el.querySelector('.' + c);
  let dias = 0;
  for (let i = 0; i < 7; i++) if (q('d' + i).checked) dias |= 1 << i;
  return {
    habilitada: q('habilitada').checked ? 'true' : 'false',
    inicio: q('inicio').value, fim: q('fim').value,
    temperaturaConforto: q('conforto').value, temperaturaEconomia: q('economia').value,
    ausenciaMinutos: q('ausencia').value,
    desligarNoFim: q('desligaFim').checked ? 'true' : 'false',
    ligarSomenteComPresenca: q('soPresenca').checked ? 'true' : 'false',
    desligarNaFaltaPresenca: q('desligaAusencia').checked ? 'true' : 'false',
    diasSemanaAtivos: String(dias),
    bloquearFimDeSemana: q('bloquearFDS').checked ? 'true' : 'false',
    // Slave sem a opção (firmware antigo): o campo não vai, e o valor salvo fica.
    ...(q('bloquearFer') ? { bloquearFeriados: q('bloquearFer').checked ? 'true' : 'false' } : {}),
    boostVentiladorAtivo: q('boost').checked ? 'true' : 'false',
    boostVentiladorLimiteC: q('boostC').value,
    restaurarEstadoAposQueda: q('restaura').checked ? 'true' : 'false'
  };
}

async function salvar(id, botao) {
  const el = botao.closest('[data-id]'), a = ambientes[id];
  const dados = lerCartao(el);
  if (!dados.inicio || !dados.fim) { aviso('Preencha o início e o fim do expediente', true); return; }
  botao.disabled = true;
  botao.textContent = 'Salvando…';
  const params = new URLSearchParams(dados);
  if (id !== 'master') params.set('id', id);
  try {
    const r = await postar((id === 'master' ? '/automacao/master?' : '/escravo/automacao?') + params.toString());
    const j = await r.json().catch(() => ({ ok: true }));
    if (j.ok === false) throw new Error(j.erro || 'O dispositivo recusou a configuração');
    a.alterado = false;
    a.lidoEm = 0;  // relê já, sem esperar os 30 s
    aviso('Automação de ' + a.nome + ' salva ✓');
    await carregar(id);
  } catch (e) {
    aviso((e.message || 'Não foi possível salvar') + (id === 'master' ? '' : ' · confira se o Slave está online'), true);
    botao.disabled = false;
    botao.textContent = 'Salvar';
  }
}

function marcarAlterado(e) {
  const el = e.target.closest('[data-id]');
  if (!el) return;
  ambientes[el.dataset.id].alterado = true;
  el.querySelector('.pendente').textContent = 'Alterações não salvas';
  if (e.target.classList.contains('habilitada')) el.classList.toggle('desativado', !e.target.checked);
}
document.getElementById('cartoes').addEventListener('input', marcarAlterado);
document.getElementById('cartoes').addEventListener('change', marcarAlterado);
window.addEventListener('beforeunload', (e) => {
  if (Object.values(ambientes).some((a) => a.alterado)) { e.preventDefault(); e.returnValue = ''; }
});

// A configuração só muda quando alguém salva: relê a cada 30 s (o status ao
// vivo vem do /nodes, a cada 5 s). Uma leitura que falha não apaga o cartão
// -- Slave com sinal fraco às vezes demora --; "Sem comunicação" só com o
// Slave fora do ar no /nodes ou depois de 3 falhas seguidas.
const RELER_CONFIG_MS = 30000, FALHAS_ATE_AVISAR = 3;
async function carregar(id) {
  const a = ambientes[id];
  if (!a || a.alterado) return;
  // Slave offline: nem tenta (cada tentativa segura o Master até o timeout).
  if (id !== 'master' && !a.online) { a.cfg = null; desenhar(); return; }
  if (a.cfg && Date.now() - (a.lidoEm || 0) < RELER_CONFIG_MS) { desenhar(); return; }
  try {
    const cfg = await buscar(id === 'master' ? '/automacao/master' : '/escravo/automacao?id=' + encodeURIComponent(id));
    // {"ok":false} = falha de comunicação Master->Slave, não uma automação de verdade.
    if (!cfg || cfg.ok === false) throw new Error('sem resposta');
    a.cfg = cfg; a.lidoEm = Date.now(); a.falhas = 0;
  } catch (_) {
    a.falhas = (a.falhas || 0) + 1;
    if (a.falhas >= FALHAS_ATE_AVISAR) a.cfg = null;
  }
  if (!a.alterado) desenhar();
}

async function atualizar() {
  try {
    const nos = await buscar('/nodes');
    conexao(true);
    const lista = (nos.master ? [{ id: 'master', nome: nos.master.nome, online: true, status: nos.master.statusAutomacao }] : [])
      .concat((nos.escravos || []).map((e) => ({ id: e.id, nome: e.nome, online: e.online, status: e.statusAutomacao })));
    ordem = lista.map((x) => x.id);
    lista.forEach((x) => {
      if (!ambientes[x.id]) ambientes[x.id] = { cfg: null, alterado: false };
      ambientes[x.id].nome = x.nome;
      ambientes[x.id].online = x.online;
      ambientes[x.id].status = x.status;
    });
    await Promise.all(ordem.map(carregar));
  } catch (_) { conexao(false); }
}
atualizar();
setInterval(atualizar, 5000);

const luzes = {};  // id -> { dados, alterado }
function cartaoLuzHTML(l) {
  return '<section class="cartao' + (l.habilitada ? '' : ' desativado') + '" data-luz="' + esc(l.id) + '">' +
    '<div class="auto-topo"><div><h4>' + esc(l.nome) + '</h4><div class="sub">' + l.luzes + (l.luzes === 1 ? ' luz' : ' luzes') +
    ' · ' + l.acesas + (l.acesas === 1 ? ' acesa' : ' acesas') + '</div></div>' +
    '<div class="auto-selos">' + (l.habilitada ? '<span class="selo ok">Ativa</span>' : '<span class="selo neutro">Desativada</span>') + '</div></div>' +
    '<div class="operacao">' + esc(l.situacao || '') + '</div>' +
    '<div class="principal-auto">' + opcao('l-habilitada', l.habilitada, 'Automação das luzes', 'Acende e apaga as luzes deste ambiente pela presença.') + '</div>' +
    '<div class="bloco"><div class="rotulo">Regras</div>' +
