const ESCUDO = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l8 3v6c0 5-3.4 9.3-8 11-4.6-1.7-8-6-8-11V5z"/><path d="M8.5 12l2.5 2.5 4.5-5"/></svg>';
// estado -> [classe do cartão de cima, título]
const ESTADOS_SEG = { armado: ['armado', 'Armado'], disparado: ['disparado', 'ALARME DISPARADO'],
