  expediente: ['livre', 'Desarmado · horário de funcionamento'], desligada: ['', 'Alarme desligado'], sem_hora: ['espera', 'Aguardando a hora certa'] };
const ORDEM_DIAS = [1, 2, 3, 4, 5, 6, 0];
