// Próxima mudança pelo horário de funcionamento (o feriado o Master resolve).
function proximaMudanca(s) {
  const agora = new Date(), min = agora.getHours() * 60 + agora.getMinutes();
  const m = (h) => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
  const hoje = s.dias[agora.getDay()];
  if (hoje.funciona && min >= m(hoje.abre) && min < m(hoje.fecha)) return 'Fecha às ' + hoje.fecha + '; depois arma quando as salas esvaziarem';
  for (let i = 0; i < 8; i++) {
    const d = (agora.getDay() + i) % 7, x = s.dias[d];
    if (!x.funciona || (i === 0 && min >= m(x.abre))) continue;
    return 'Desarma ' + (i === 0 ? 'hoje' : i === 1 ? 'amanhã' : NOME_DIA[d].toLowerCase()) + ' às ' + x.abre;
  }
  return 'Nenhum dia de funcionamento: fica armado direto';
}
function heroHTML(s) {
  const e = ESTADOS_SEG[s.estado] || ['', s.estado];
  const chips = [];
  if (s.habilitada) chips.push(s.modoTeste ? '<span class="alerta">Modo teste: só registra</span>' : '<span>Disparos de verdade</span>');
  chips.push(s.hub ? '<span>Hub conectado</span>' : '<span class="alerta">Hub desconectado: sem avisos</span>');
  if (s.habilitada && s.estado !== 'sem_hora') chips.push('<span>' + esc(proximaMudanca(s)) + '</span>');
  const botao = ['armado', 'disparado', 'aguardando'].includes(s.estado)
    ? '<button class="btn ' + (s.estado === 'disparado' ? 'btn-claro' : 'btn-principal') + '" type="button" onclick="desarmarSeg(this)">Desarmar agora</button>'
    : !s.habilitada ? '<button class="btn btn-principal" type="button" onclick="abaSeg(\'regras\')">Ligar o alarme</button>' : '';
  // A frase do Master repete o título: no cartão fica só o que acrescenta.
  const desde = /desde ([\d/]+ [\d:]{5})/.exec(s.situacao || '');
  const sub = s.estado === 'armado' ? (desde ? 'Desde ' + desde[1] : '') : s.estado === 'expediente' ? '' : s.situacao;
  return '<div class="ic">' + ESCUDO + '</div><div class="txt"><h2>' + e[1] + '</h2>' + (sub ? '<p>' + esc(sub) + '</p>' : '<p></p>') +
    '<div class="chips">' + chips.join('') + '</div></div>' + botao;
}
function salaHTML(a) {
  const t = a.situacao || '';
  const cor = !a.vigiado ? '' : /fora do ar/i.test(t) ? 'perigo' : /presen|gente/i.test(t) ? 'aviso' : 'ok';
  return '<span><i class="pt ' + cor + '"></i>' + esc(a.nome) + ' <small>' + esc(a.vigiado ? t.toLowerCase() : 'fora do alarme') + '</small></span>';
}
// Eventos agrupados por dia ("dd/mm HH:MM:SS"), com uma cor por tipo.
function corEvento(t) {
  return /DISPARO/.test(t) ? 'perigo' : /TESTE|fora do ar|desconectado/i.test(t) ? 'aviso' : /^Armado/.test(t) ? 'acento' : /Desarmado|voltou|conectado/i.test(t) ? 'ok' : '';
}
function eventosHTML(lista) {
  if (!lista.length) return '<p class="desc" style="margin:0">Nenhum evento ainda.</p>';
  const hoje = new Date(), ontem = new Date(Date.now() - 864e5);
  const dm = (d) => String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0');
  const mostrar = evTodos ? lista : lista.slice(0, 15);
