    h += '<div class="ev"><i class="pt ' + corEvento(e.texto) + '"></i><time>' + esc(e.hora.slice(6, 11)) + '</time><span>' + esc(e.texto) + '</span></div>';
  }
  if (lista.length > 15) h += '<button class="btn btn-claro btn-pequeno ev-mais" type="button" onclick="evTodos=!evTodos;htmlEv=\'\';desenharSeg()">' + (evTodos ? 'Mostrar menos' : 'Ver todos (' + lista.length + ')') + '</button>';
