</main></div><div class="toast" id="toast"></div><script>
let falhas = 0, ultimaAtualizacao = 0;
// Opção liga/desliga e campo de formulário (Automações e Segurança).
function opcao(classe, marcado, titulo, detalhe) {
  return '<label class="opcao"><span>' + titulo + (detalhe ? '<small>' + detalhe + '</small>' : '') + '</span>' +
    '<input type="checkbox" class="chk ' + classe + '"' + (marcado ? ' checked' : '') + '></label>';
}
function campo(classe, rotulo, tipo, valor, extra) {
  return '<label>' + rotulo + '<input class="' + classe + '" type="' + tipo + '" value="' + esc(valor) + '" ' + (extra || '') + '></label>';
}
function esc(t) {
  return String(t == null ? '' : t).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function numero(v, casas) { return Number(v).toFixed(casas).replace('.', ','); }
function temValor(v) { return v !== null && v !== undefined && v !== '' && !isNaN(v); }
function aviso(texto, erro) {
  const t = document.getElementById('toast');
  t.textContent = texto;
  t.className = 'toast visivel' + (erro ? ' erro' : '');
  clearTimeout(aviso.timer);
  aviso.timer = setTimeout(() => { t.className = 'toast' + (erro ? ' erro' : ''); }, erro ? 4000 : 1800);
}
async function postar(rota) {
  const r = await fetch(rota, { method: 'POST', cache: 'no-store' });
  if (r.status === 401) { location.href = '/login'; throw new Error('Sessão expirada'); }
  if (!r.ok) {
    let detalhe = 'Erro HTTP ' + r.status;
    try { const j = await r.json(); if (j.erro) detalhe = j.erro; } catch (_) { }
    throw new Error(detalhe);
  }
  return r;
}
// Leituras uma de cada vez: cada resposta passa pelos buffers de Wi-Fi da
// RAM interna do Master, e várias juntas eram os picos de memória (ver
// MUDANCAS, "Medidas de memória"). A mesma rota já na fila não entra de novo.
let filaLeituras = Promise.resolve();
const leiturasNaFila = new Map();
function buscar(rota) {
  if (leiturasNaFila.has(rota)) return leiturasNaFila.get(rota);
  const vez = filaLeituras.then(async () => {
    // Sem resposta em 8 s: desiste, para uma leitura presa não parar a fila.
    const limite = new AbortController();
    const relogio = setTimeout(() => limite.abort(), 8000);
    try {
      const r = await fetch(rota + (rota.indexOf('?') < 0 ? '?' : '&') + 't=' + Date.now(), { cache: 'no-store', signal: limite.signal });
      if (r.status === 401) { location.href = '/login'; throw new Error('401'); }
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } finally { clearTimeout(relogio); leiturasNaFila.delete(rota); }
  });
  leiturasNaFila.set(rota, vez);
  filaLeituras = vez.catch(() => { });
  return vez;
}
function conexao(ok) {
  falhas = ok ? 0 : falhas + 1;
  const caiu = falhas >= 2;
  document.body.classList.toggle('desconectado', caiu);
  document.getElementById('estadoLateral').innerHTML = caiu
    ? '<span class="ponto off"></span><span style="color:var(--perigo)">Reconectando…</span>'
    : '<span class="ponto"></span><span style="color:var(--ok)">Hub online</span>';
  if (ok) ultimaAtualizacao = Date.now();
}
function segundosDesde() {
  return ultimaAtualizacao ? 'há ' + Math.round((Date.now() - ultimaAtualizacao) / 1000) + ' s' : '---';
}
document.getElementById('hostLateral').textContent = location.hostname;

const NOMES_MES = ['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
let relDados = null, relParamAlterado = false, relDiasMes = [];
const DIAS_SEM = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'];
function horas(min) {
  if (!min) return '0 h';
  if (min < 60) return min + ' min';
  const h = Math.floor(min / 60), m = min % 60;
  return h + ' h' + (m ? ' ' + String(m).padStart(2, '0') : '');
}
function reais(v) { return 'R$ ' + v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function nomeMes(m) { const [a, n] = m.split('-'); return NOMES_MES[Number(n) - 1] + ' ' + a; }
function desenharRelatorio(d) {
  // Logo depois de reiniciar, o Master ainda não sabe a data (sem a hora da
  // internet) e responde sem mês: avisa e tenta de novo em 5 s, em vez de
  // mostrar "sem dados" como se o histórico tivesse sumido.
  if (!d.mes) {
    document.getElementById('relAmbientes').innerHTML =
      '<tr><td colspan="8" class="rel-vazio">O Master acabou de reiniciar: carregando o histórico…</td></tr>';
    clearTimeout(desenharRelatorio.denovo);
    desenharRelatorio.denovo = setTimeout(atualizarRelatorio, 5000);
    return;
  }
  relDados = d;
  const sel = document.getElementById('relMes');
  const meses = d.meses.slice().sort().reverse();
  const opcoes = meses.map((m) => '<option value="' + m + '">' + nomeMes(m) + '</option>').join('');
  if (sel.dataset.opcoes !== opcoes) { sel.innerHTML = opcoes; sel.dataset.opcoes = opcoes; }
  if (d.mes) sel.value = d.mes;
  document.getElementById('relCsv').href = '/historico/csv?mes=' + encodeURIComponent(d.mes || '');
  if (!relParamAlterado) {
    document.getElementById('relKw').value = d.potenciaKw;
    document.getElementById('relTarifa').value = d.tarifa;
  }
  const av = document.getElementById('relAviso');
  const msg = !d.flash ? 'O arquivo do histórico não abriu: os números de hoje valem só até o hub reiniciar.'
    : !d.horaConfiavel ? 'Hub sem hora confiável: o histórico volta a contar quando a hora da internet chegar.' : '';
  av.textContent = msg; av.style.display = msg ? 'block' : 'none';

  // Linha: [dia, id, nome, ligado, presenca, ligadoVazio, poupado, economico, offline, medidos, temp10, deslig]
  const amb = {}, dias = {};
  let ligado = 0, poupado = 0, vazio = 0, deslig = 0;
  for (const l of d.linhas) {
    const a = amb[l[1]] || (amb[l[1]] = { id: l[1], nome: l[2], ligado: 0, vazio: 0, poupado: 0, econ: 0, temp: 0, nTemp: 0,
      kwProprio: (d.potencias || {})[l[1]] || 0 });
    a.nome = l[2]; a.ligado += l[3]; a.vazio += l[5]; a.poupado += l[6]; a.econ += l[7];
    if (l[10] !== null) { a.temp += l[10] * l[9]; a.nTemp += l[9]; }
    const dia = dias[l[0]] || (dias[l[0]] = { ligado: 0, poupado: 0 });
    dia.ligado += l[3]; dia.poupado += l[6];
    ligado += l[3]; poupado += l[6]; vazio += l[5]; deslig += l[11];
  }
  // Cada ambiente com a potência dele (ou a padrão).
  for (const id in amb) amb[id].kw = amb[id].kwProprio || d.potenciaKw;
  const kwh = Object.values(amb).reduce((s, a) => s + a.poupado / 60 * a.kw, 0);
  document.getElementById('relReais').textContent = reais(kwh * d.tarifa);
  document.getElementById('relPct').textContent = ligado + poupado
    ? Math.round(100 * poupado / (ligado + poupado)) + '% menos horas de ar no expediente' : 'sem dados no mês ainda';
  document.getElementById('relKwh').innerHTML = numero(kwh, kwh < 100 ? 1 : 0) + ' <small>kWh</small>';
  document.getElementById('relPoupado').textContent = horas(poupado);
  document.getElementById('relDeslig').textContent = deslig + (deslig === 1 ? ' desligamento' : ' desligamentos') + ' por ausência';
  document.getElementById('relLigado').textContent = horas(ligado);
  document.getElementById('relVazio').textContent = horas(vazio) + ' ligado sem ninguém na sala';

  // Gráfico por dia: o mês inteiro no eixo; os dias que ainda não chegaram
  // ficam vazios, para as barras não esticarem no começo do mês.
  const [ano, mesN] = (d.mes || '2000-01').split('-').map(Number);
  const totalDias = new Date(ano, mesN, 0).getDate();
  const hoje = d.hoje && d.hoje.startsWith(d.mes) ? Number(d.hoje.slice(8)) : totalDias + 1;
  let maior = 0;
  for (const k in dias) maior = Math.max(maior, dias[k].ligado + dias[k].poupado);
  // Escala em horas redondas, com no máximo 4 linhas de grade.
  const passo = [1, 2, 4, 6, 8, 12, 24, 48, 96, 168].find((p) => maior / 60 / p <= 4) || 336;
  const topo = Math.max(1, Math.ceil(maior / 60 / passo)) * passo * 60;
  let grade = '', rotulos = '';
  for (let h = 0; h <= topo / 60; h += passo) {
    const y = 100 * h * 60 / topo;
    grade += '<i style="bottom:' + y + '%"></i>';
    rotulos += '<span style="bottom:' + y + '%">' + h + ' h</span>';
  }
  relDiasMes = [];
  let barras = '', eixo = '';
  for (let i = 1; i <= totalDias; i++) {
    const v = dias[i] || { ligado: 0, poupado: 0 };
    const sem = new Date(ano, mesN - 1, i).getDay();
    relDiasMes[i] = { v, sem, futuro: i > hoje };
    const corpo = i > hoje ? '' : !v.ligado && !v.poupado ? '<i class="zero"></i>'
      : (v.poupado ? '<i class="p" style="height:' + (100 * v.poupado / topo) + '%"></i>' : '') +
        (v.ligado ? '<i class="l" style="height:' + (100 * v.ligado / topo) + '%"></i>' : '');
    barras += '<div class="rel-dia" data-dia="' + i + '">' + corpo + '</div>';
    eixo += '<span class="' + (i === 1 || i % 5 === 0 ? 'marca' : '') + (sem === 0 || sem === 6 ? ' fds' : '') + (i === hoje ? ' hoje marca' : '') + '">' + i + '</span>';
  }
  document.getElementById('relGrade').innerHTML = grade;
  document.getElementById('relY').innerHTML = rotulos;
  document.getElementById('relDias').innerHTML = barras;
  document.getElementById('relEixo').innerHTML = eixo;

  const lista = Object.values(amb).sort((a, b) => b.poupado - a.poupado || a.nome.localeCompare(b.nome));
  document.getElementById('relQtd').textContent = lista.length ? lista.length + (lista.length === 1 ? ' ambiente' : ' ambientes') : '';
  // Não redesenha a tabela enquanto alguém digita uma potência nela.
  if (document.activeElement && document.activeElement.classList.contains('rel-kw')) return;
  document.getElementById('relAmbientes').innerHTML = lista.length ? lista.map((a) =>
    '<tr><td><b>' + esc(a.nome) + '</b></td><td>' + horas(a.ligado) + '</td><td>' + horas(a.vazio) + '</td><td>' + horas(a.poupado) +
    '</td><td>' + horas(a.econ) + '</td><td>' + (a.nTemp ? numero(a.temp / a.nTemp / 10, 1) + ' °C' : '---') +
    '</td><td><input class="rel-kw" type="number" step="0.1" min="0.1" max="10" inputmode="decimal" aria-label="Potência de ' + esc(a.nome) +
    ' (kW)" data-id="' + esc(a.id) + '" placeholder="' + d.potenciaKw + '" value="' + (a.kwProprio || '') + '">' +
    '</td><td>' + reais(a.poupado / 60 * a.kw * d.tarifa) + '</td></tr>').join('')
    : '<tr><td colspan="8" class="rel-vazio">Sem dados neste mês ainda. O Master anota a cada minuto; os primeiros números aparecem em instantes.</td></tr>';
}
// Caixinha com os números do dia ao passar o mouse (ou tocar) numa barra.
function dicaDia(ev) {
  const el = ev.target.closest('.rel-dia'), tip = document.getElementById('relTip');
  const info = el && relDiasMes[el.dataset.dia];
  if (!info) { tip.style.display = 'none'; return; }
  const [, mesN] = relDados.mes.split('-');
  tip.innerHTML = '<b>' + DIAS_SEM[info.sem] + ', ' + el.dataset.dia + '/' + Number(mesN) + '</b>' + (info.futuro ? '<br>ainda não chegou'
    : '<br><em style="background:var(--acento)"></em>Ar ligado: <b>' + horas(info.v.ligado) + '</b>' +
      '<br><em style="background:var(--ok)"></em>Desligado pela automação: <b>' + horas(info.v.poupado) + '</b>');
  const graf = tip.parentElement.getBoundingClientRect(), r = el.getBoundingClientRect();
  tip.style.display = 'block';
  const x = r.left - graf.left + r.width / 2 - tip.offsetWidth / 2;
  tip.style.left = Math.max(0, Math.min(graf.width - tip.offsetWidth, x)) + 'px';
  tip.style.top = '-8px';
}
document.getElementById('relDias').addEventListener('pointermove', dicaDia);
document.getElementById('relDias').addEventListener('pointerleave', () => { document.getElementById('relTip').style.display = 'none'; });
async function atualizarRelatorio() {
  const sel = document.getElementById('relMes');
  try {
    desenharRelatorio(await buscar('/historico' + (sel.value ? '?mes=' + encodeURIComponent(sel.value) : '')));
    conexao(true);
  } catch (_) { conexao(false); }
}
document.getElementById('relMes').addEventListener('change', atualizarRelatorio);
// Potência de um ambiente: grava ao sair do campo (vazio = volta à padrão).
document.getElementById('relAmbientes').addEventListener('change', async (e) => {
  if (!e.target.classList.contains('rel-kw')) return;
  try {
    const corpo = new URLSearchParams({ id: e.target.dataset.id, potenciaKw: e.target.value || '0' });
    const r = await fetch('/historico/potencia', { method: 'POST', body: corpo, cache: 'no-store' });
    if (r.status === 401) { location.href = '/login'; return; }
    let j = {}; try { j = await r.json(); } catch (_) { }
