<div data-aba="outra" hidden><div class="cartao"><b id="outraTitulo"></b><p style="color:var(--texto2);margin:8px 0 0">Esta parte ainda está no painel do Master. Ela passa para o hub junto com a próxima atualização dos Slaves.</p></div></div>
</main></div><div class="toast" id="toast"></div><script>
let falhas = 0, ultimaAtualizacao = 0;
// Opção liga/desliga e campo de formulário (Automações e Segurança).
function opcao(classe, marcado, titulo, detalhe) {
  return '<label class="opcao"><span>' + titulo + (detalhe ? '<small>' + detalhe + '</small>' : '') + '</span>' +
    '<input type="checkbox" class="chk ' + classe + '"' + (marcado ? ' checked' : '') + '></label>';
}
function campo(classe, rotulo, tipo, valor, extra) {
  return '<label>' + rotulo + '<input class="' + classe + '" type="' + tipo + '" value="' + esc(valor) + '" ' + (extra || '') + '></label>';
}
function esc(t) {
  return String(t == null ? '' : t).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function numero(v, casas) { return Number(v).toFixed(casas).replace('.', ','); }
function temValor(v) { return v !== null && v !== undefined && v !== '' && !isNaN(v); }
function aviso(texto, erro) {
  const t = document.getElementById('toast');
  t.textContent = texto;
  t.className = 'toast visivel' + (erro ? ' erro' : '');
  clearTimeout(aviso.timer);
  aviso.timer = setTimeout(() => { t.className = 'toast' + (erro ? ' erro' : ''); }, erro ? 4000 : 1800);
}
async function postar(rota) {
  const r = await fetch(rota, { method: 'POST', cache: 'no-store' });
  if (r.status === 401) { location.href = '/login'; throw new Error('Sessão expirada'); }
  if (!r.ok) {
    let detalhe = 'Erro HTTP ' + r.status;
    try { const j = await r.json(); if (j.erro) detalhe = j.erro; } catch (_) { }
    throw new Error(detalhe);
  }
  return r;
}
// Leituras uma de cada vez: cada resposta passa pelos buffers de Wi-Fi da
// RAM interna do Master, e várias juntas eram os picos de memória (ver
// MUDANCAS, "Medidas de memória"). A mesma rota já na fila não entra de novo.
let filaLeituras = Promise.resolve();
const leiturasNaFila = new Map();
function buscar(rota) {
  if (leiturasNaFila.has(rota)) return leiturasNaFila.get(rota);
  const vez = filaLeituras.then(async () => {
    // Sem resposta em 8 s: desiste, para uma leitura presa não parar a fila.
    const limite = new AbortController();
    const relogio = setTimeout(() => limite.abort(), 8000);
    try {
      const r = await fetch(rota + (rota.indexOf('?') < 0 ? '?' : '&') + 't=' + Date.now(), { cache: 'no-store', signal: limite.signal });
      if (r.status === 401) { location.href = '/login'; throw new Error('401'); }
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } finally { clearTimeout(relogio); leiturasNaFila.delete(rota); }
  });
  leiturasNaFila.set(rota, vez);
  filaLeituras = vez.catch(() => { });
  return vez;
}
function conexao(ok) {
  falhas = ok ? 0 : falhas + 1;
  const caiu = falhas >= 2;
  document.body.classList.toggle('desconectado', caiu);
  document.getElementById('estadoLateral').innerHTML = caiu
    ? '<span class="ponto off"></span><span style="color:var(--perigo)">Reconectando…</span>'
    : '<span class="ponto"></span><span style="color:var(--ok)">Hub online</span>';
  if (ok) ultimaAtualizacao = Date.now();
}
function segundosDesde() {
  return ultimaAtualizacao ? 'há ' + Math.round((Date.now() - ultimaAtualizacao) / 1000) + ' s' : '---';
}
document.getElementById('hostLateral').textContent = location.hostname;

const NOMES_ABA = {};
function mostrarAba() {
  const h = location.hash.slice(1);
  const v = ['ir', 'zigbee', 'firmware', 'rede', 'sensores'].includes(h) ? h : 'zigbee';
  const prontas = ['ir', 'zigbee', 'firmware', 'sensores', 'rede'];
  document.querySelectorAll('[data-aba]').forEach((el) => { el.hidden = el.dataset.aba !== (prontas.includes(v) ? v : 'outra'); });
  document.getElementById('outraTitulo').textContent = NOMES_ABA[v] || '';
  document.querySelectorAll('.aba[data-secao],.subnav a[data-secao]').forEach((b) => b.classList.toggle('ativo', b.dataset.secao === v));
}
document.querySelectorAll('.aba[data-secao]').forEach((b) => b.addEventListener('click', () => { location.hash = b.dataset.secao; }));
window.addEventListener('hashchange', mostrarAba);
mostrarAba();

let zig = null, achados = null, ambientes = [], htmlNovos = '', htmlLista = '';
const TECLA_NOME = { left: 'esquerda', center: 'meio', right: 'direita', top: 'de cima', bottom: 'de baixo', middle: 'meio' };
const TECLA = new Proxy(TECLA_NOME, { get: (t, k) => t[k] || (/^l\d+$/.test(k) ? k.slice(1) : undefined) });
function opcoesSalas(escolhida) {
  return '<option value="">Escolha a sala</option>' + ambientes.map((a) =>
    '<option value="' + esc(a.id) + '"' + (a.id === escolhida ? ' selected' : '') + '>' + esc(a.nome) + '</option>').join('');
}
function desenhar() {
  if (!zig || !achados) return;
  const st = document.getElementById('zigStatus');
  st.className = 'selo ' + (zig.zigbee2mqttOnline ? 'ok' : 'aviso');
  st.textContent = zig.zigbee2mqttOnline ? 'Zigbee2MQTT no ar' : 'Zigbee2MQTT sem resposta';
  const nomeSala = (id) => (ambientes.find((a) => a.id === id) || {}).nome || id;
  const lista = zig.dispositivos.length ? zig.dispositivos.map((d) =>
    '<div class="zig-item"><div><b>' + (d.tipo === 'cortina' ? '🪟 ' : '💡 ') + esc(d.nome) + '</b><small>' + esc(nomeSala(d.ambiente)) +
    ' · ' + esc(d.id) + (d.canal ? ' (' + esc(TECLA[d.canal] || d.canal) + ')' : '') + '</small></div>' +
    '<button class="btn btn-claro btn-pequeno" type="button" data-remover="' + esc(d.id) + '|' + esc(d.canal) + '">Remover</button></div>').join('')
    : '<p class="desc" style="margin:0">Nenhum ainda.</p>';
  if (lista !== htmlLista) { htmlLista = lista; document.getElementById('zigLista').innerHTML = lista; }
  const caixa = document.getElementById('zigNovos');
  if (caixa.contains(document.activeElement)) return;   // não atrapalha quem está digitando
  const novos = achados.aparelhos.filter((a) => a.canais.some((c) => !c.vinculado));
  const html = novos.length ? novos.map((a) => '<div class="zig-novo" data-id="' + esc(a.id) + '" style="padding:10px 0;border-bottom:1px solid var(--card-borda)">' +
    '<b style="font-size:14px">' + esc(a.id) + '</b><small style="display:block;color:var(--texto3);font-size:12px">' + esc([a.fabricante, a.modelo].filter(Boolean).join(' · ')) +
    ' · ' + a.canais.length + (a.canais[0].tipo === 'cortina' ? ' cortina' : a.canais.length === 1 ? ' luz' : ' teclas') + '</small>' +
    a.canais.filter((c) => !c.vinculado).map((c) => '<label>' + (c.tipo === 'cortina' ? '🪟 ' : '💡 ') + (c.canal ? 'Tecla ' + esc(TECLA[c.canal] || c.canal) : 'Nome') +
      '<input class="zn" data-canal="' + esc(c.canal) + '" data-tipo="' + c.tipo + '" maxlength="32" value="' + esc(c.sugestao) + '"></label>').join('') +
    '<label>Sala<select class="zs">' + opcoesSalas('') + '</select></label>' +
    '<button class="btn btn-principal" type="button" data-vincular="' + esc(a.id) + '">Vincular</button></div>').join('')
    : '<p class="desc" style="margin:0">Nenhum aparelho novo. Para incluir um, use "Parear aparelho novo".</p>';
  if (html !== htmlNovos) { htmlNovos = html; caixa.innerHTML = html; }
  const p = document.getElementById('zigParearTxt');
  p.className = 'retorno' + (achados.pareando ? ' ok' : '');
  p.textContent = achados.pareando ? 'Pareamento aberto por mais ' + achados.pareando + ' s: coloque o aparelho em modo de pareamento agora.' : '';
}
async function atualizar() {
  try {
    const [z, d, n] = await Promise.all([buscar('/zigbee'), buscar('/zigbee/descobertos'), buscar('/nodes')]);
    zig = z; achados = d;
    ambientes = (n.escravos || []).map((e) => ({ id: e.id, nome: e.nome }));
    document.getElementById('ipLateral').textContent = n.hub ? n.hub.ip : '';
    conexao(true); desenhar();
  } catch (_) { conexao(false); }
}
document.getElementById('zigParear').addEventListener('click', async (e) => {
  e.target.disabled = true;
  try { await postar('/zigbee/parear'); aviso('Pareamento aberto por 2 minutos'); await atualizar(); }
  catch (err) { aviso(err.message, true); }
  e.target.disabled = false;
});
document.getElementById('zigNovos').addEventListener('click', async (e) => {
  const b = e.target.closest('[data-vincular]');
  if (!b) return;
  const bloco = b.closest('.zig-novo'), sala = bloco.querySelector('.zs').value;
  if (!sala) { aviso('Escolha a sala', true); return; }
  b.disabled = true;
  try {
    for (const campo of bloco.querySelectorAll('.zn'))
      await postar('/zigbee/dispositivo?' + new URLSearchParams({ id: b.dataset.vincular, canal: campo.dataset.canal,
        tipo: campo.dataset.tipo, nome: campo.value.trim(), ambiente: sala }).toString());
    aviso('Vinculado ✓'); htmlNovos = ''; document.activeElement.blur(); await atualizar();
  } catch (err) { aviso(err.message, true); b.disabled = false; }
});
document.getElementById('zigLista').addEventListener('click', async (e) => {
  const b = e.target.closest('[data-remover]');
  if (!b) return;
  const [id, canal] = b.dataset.remover.split('|');
  if (!confirm('Remover este aparelho do painel? Ele continua pareado no hub.')) return;
  try { await postar('/zigbee/dispositivo?' + new URLSearchParams({ id, canal, acao: 'remover' }).toString()); htmlLista = ''; htmlNovos = ''; await atualizar(); }
  catch (err) { aviso(err.message, true); }
});
atualizar();
setInterval(atualizar, 3000);

// ---------- Sensores e rede (comandos pelo hub: accontrol/slave/<MAC>/set) ----------
let sx = null, htmlSx = '', htmlPot = '';
async function admin(mac, campos, ok) {
  const r = await fetch('/accontrol/api/admin', { method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify(Object.assign({ mac }, campos)) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || j.ok === false) throw new Error(j.erro || 'O Slave não respondeu');
  if (ok) aviso(ok);
  setTimeout(atualizarSx, 1500);
}
function situacaoSensor(x) {
  return !x.contato ? '<span class="selo aviso">sem contato</span>' : !x.radarOk ? '<span class="selo aviso">radar com problema</span>'
    : x.presenca ? '<span class="selo ok">vendo alguém</span>' : '<span class="selo neutro">sala vazia</span>';
}
function desenharSx() {
  if (!sx) return;
  const h = sx.length ? sx.map((e) => {
    const d = e.dados;
    let corpo;
    if (!e.online) corpo = '<p class="desc">Slave fora do ar.</p>';
    else if (!d) corpo = '<p class="desc">Lendo os sensores…</p>';
    else {
      const bt = typeof d.radarBluetooth === 'boolean' ? '<label class="chk-linha">Bluetooth do radar (app HLKRadarTools)<input type="checkbox" class="chk" data-bt-radar="' + esc(e.mac) + '"' +
        (d.radarBluetooth ? ' checked' : '') + (e.comandavel ? '' : ' disabled') + '></label>' : '';
      corpo = bt + ((d.sensores || []).length ? d.sensores.map((x) => '<div class="zig-item"><div><b>Sensor ' + esc(x.mac.slice(-8)) + '</b><small>' +
        (x.contato ? 'sinal ' + x.rssi + ' dBm · v' + esc(x.versao) : 'último contato há ' + (x.haSegundos < 0 ? '?' : x.haSegundos + ' s')) +
        '</small></div><div>' + situacaoSensor(x) + ' <button class="btn btn-claro btn-pequeno" type="button" data-remover-sx="' + esc(e.mac) + '|' + esc(x.mac) + '"' +
        (e.comandavel ? '' : ' disabled') + '>Remover</button></div></div>' +
        (x.contato && typeof x.bluetooth === 'boolean' ? '<label class="chk-linha">Bluetooth do radar deste sensor<input type="checkbox" class="chk" data-bt-sx="' +
          esc(e.mac) + '|' + esc(x.mac) + '"' + (x.bluetooth ? ' checked' : '') + (e.comandavel ? '' : ' disabled') + '></label>' : '')).join('')
        : '<p class="desc">Nenhum sensor extra.</p>') +
        (d.vinculando ? '<p class="retorno ok">Aguardando o sensor (até 60 s)… deixe-o ligado perto do Slave.</p>'
          : '<button class="btn btn-claro btn-pequeno" type="button" data-vincular-sx="' + esc(e.mac) + '"' + (e.comandavel ? '' : ' disabled') + '>Vincular sensor</button>');
    }
    if (e.online && !e.comandavel) corpo += '<p class="nota" style="font-size:12px;color:var(--texto3)">Atualize o firmware deste Slave para mexer por aqui.</p>';
    return '<section class="cartao"><h4>' + esc(e.nome) + '</h4>' + corpo + '</section>';
  }).join('') : '<div class="cartao"><p class="desc" style="margin:0">Nenhum Slave ainda.</p></div>';
  if (h !== htmlSx && !document.getElementById('sxLista').contains(document.activeElement)) { htmlSx = h; document.getElementById('sxLista').innerHTML = h; }
  const p = sx.filter((e) => e.online && e.dados).map((e) => '<div class="zig-item"><div><b>' + esc(e.nome) + '</b><small>agora: ' +
    numero(e.dados.wifiTxDbm, 1) + ' dBm</small></div><select data-pot="' + esc(e.mac) + '" style="width:auto"' + (e.comandavel ? '' : ' disabled') + '>' +
    [8.5, 11].map((v) => '<option value="' + v + '"' + (Math.abs(e.dados.wifiTxDbm - v) < 0.1 ? ' selected' : '') + '>' + numero(v, 1) + ' dBm</option>').join('') +
    '</select></div>').join('') || '<p class="desc" style="margin:0">Nenhum Slave respondendo.</p>';
  if (p !== htmlPot && !document.getElementById('potLista').contains(document.activeElement)) { htmlPot = p; document.getElementById('potLista').innerHTML = p; }
}
async function atualizarSx() { try { sx = await buscar('/accontrol/api/sensores'); desenharSx(); } catch (_) { } }
document.getElementById('sxLista').addEventListener('click', async (e) => {
  const v = e.target.closest('[data-vincular-sx]'), r = e.target.closest('[data-remover-sx]');
  try {
    if (v) await admin(v.dataset.vincularSx, { acao: 'sensorVincular' }, 'Vínculo aberto por 60 s');
    if (r) {
      const [mac, sensor] = r.dataset.removerSx.split('|');
      if (confirm('Remover este sensor do Slave?')) await admin(mac, { acao: 'sensorRemover', mac: sensor }, 'Sensor removido');
    }
  } catch (err) { aviso(err.message, true); }
});
document.getElementById('sxLista').addEventListener('change', async (e) => {
  const t = e.target;
  try {
    if (t.dataset.btRadar) await admin(t.dataset.btRadar, { acao: 'radarBluetooth', ligado: String(t.checked) }, 'Bluetooth do radar ' + (t.checked ? 'ligado' : 'desligado'));
    if (t.dataset.btSx) { const [mac, sensor] = t.dataset.btSx.split('|'); await admin(mac, { acao: 'sensorBluetooth', mac: sensor, ligado: String(t.checked) }, 'Pedido enviado ao sensor'); }
  } catch (err) { aviso(err.message, true); t.checked = !t.checked; }
  t.blur();
});
document.getElementById('potLista').addEventListener('change', async (e) => {
  const t = e.target;
  if (!t.dataset.pot) return;
  try { await admin(t.dataset.pot, { acao: 'potencia', dbm: t.value }, 'Potência alterada'); } catch (err) { aviso(err.message, true); }
  t.blur();
});
document.getElementById('wsEnviar').addEventListener('click', async () => {
  const ssid = document.getElementById('wsSsid').value.trim(), senha = document.getElementById('wsSenha').value;
  if (!ssid) { aviso('Informe o nome da rede', true); return; }
  const alvos = (sx || []).filter((e) => e.online && e.comandavel);
  if (!alvos.length) { aviso('Nenhum Slave ligado ao hub', true); return; }
  if (!confirm('Trocar a rede de ' + alvos.length + ' Slave(s) para "' + ssid + '"? Eles vão reiniciar.')) return;
  const txt = document.getElementById('wsTxt'); let ok = 0;
  for (const e of alvos) { try { await admin(e.mac, { acao: 'wifi', ssid, senha }); ok++; } catch (_) { } }
  txt.className = 'retorno ' + (ok === alvos.length ? 'ok' : 'erro');
  txt.textContent = ok + ' de ' + alvos.length + ' Slave(s) receberam a rede nova.';
  document.getElementById('wsSenha').value = '';
});
atualizarSx();
setInterval(atualizarSx, 4000);
// Redes pelo rádio do hub (os Slaves não procuram conectados: tiraria o rádio do canal).
async function buscarRedes() {
  const b = document.getElementById('wsBuscar'), t = document.getElementById('wsBuscaTxt');
  b.disabled = true; t.className = 'retorno'; t.textContent = 'Procurando redes…';
  try {
    const j = await buscar('/accontrol/api/wifi-redes');
    if (j.erro) throw new Error(j.erro);
    document.getElementById('wsRedes').innerHTML = j.redes.map((r) => '<option value="' + esc(r.ssid) + '" label="' + esc(r.ssid) + ' (sinal ' + r.sinal + '%)">').join('');
    t.className = 'retorno ok';
    t.textContent = j.redes.length ? j.redes.length + ' rede(s) encontrada(s): toque no campo do nome para escolher.' : 'Nenhuma rede encontrada.';
  } catch (err) { t.className = 'retorno erro'; t.textContent = 'Não deu para procurar pelo hub (' + err.message + '). Digite o nome da rede.'; }
  b.disabled = false;
}
document.getElementById('wsBuscar').addEventListener('click', buscarRedes);

// ---------- Controles de IR: perfil pela marca, com teste e aprovação ----------
