  'Electrolux': [['ELECTRA_AC'], ['COOLIX'], ['GREE'], ['MIDEA']],
  'Consul / Brastemp': [['WHIRLPOOL_AC'], ['MIDEA'], ['COOLIX']],
  'Philco / Britânia': [['COOLIX'], ['TCL112AC'], ['MIDEA'], ['GREE']],
  'Agratto / Komeco / EOS': [['COOLIX'], ['GREE'], ['MIDEA'], ['TCL112AC']],
  'TCL / Semp': [['TCL112AC'], ['TEKNOPOINT'], ['COOLIX']],
  'Daikin': [['DAIKIN'], ['DAIKIN2'], ['DAIKIN152'], ['DAIKIN160'], ['DAIKIN176'], ['DAIKIN216'], ['DAIKIN64'], ['DAIKIN128']],
