};
let salasIr = [], htmlIr = '';
const assistente = {};   // id do ambiente -> { marca, i, etapa: 'liga' | 'muda' | 'fim', texto }
function cartaoIr(a) {
  const w = assistente[a.id];
  let corpo;
  if (a.viaMaster) corpo = '<p class="desc">O controle desta sala, por enquanto, se ajusta no painel do Master.</p>';
