function esc(t) {
  return String(t == null ? '' : t).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function numero(v, casas) { return Number(v).toFixed(casas).replace('.', ','); }
function temValor(v) { return v !== null && v !== undefined && v !== '' && !isNaN(v); }
function aviso(texto, erro) {
  const t = document.getElementById('toast');
  t.textContent = texto;
  t.className = 'toast visivel' + (erro ? ' erro' : '');
  clearTimeout(aviso.timer);
  aviso.timer = setTimeout(() => { t.className = 'toast' + (erro ? ' erro' : ''); }, erro ? 4000 : 1800);
}
async function postar(rota) {
  const r = await fetch(rota, { method: 'POST', cache: 'no-store' });
  if (r.status === 401) { location.href = '/login'; throw new Error('Sessão expirada'); }
  if (!r.ok) {
    let detalhe = 'Erro HTTP ' + r.status;
    try { const j = await r.json(); if (j.erro) detalhe = j.erro; } catch (_) { }
    throw new Error(detalhe);
  }
  return r;
}
// Leituras uma de cada vez: cada resposta passa pelos buffers de Wi-Fi da
// RAM interna do Master, e várias juntas eram os picos de memória (ver
// MUDANCAS, "Medidas de memória"). A mesma rota já na fila não entra de novo.
let filaLeituras = Promise.resolve();
const leiturasNaFila = new Map();
function buscar(rota) {
  if (leiturasNaFila.has(rota)) return leiturasNaFila.get(rota);
  const vez = filaLeituras.then(async () => {
    // Sem resposta em 8 s: desiste, para uma leitura presa não parar a fila.
    const limite = new AbortController();
    const relogio = setTimeout(() => limite.abort(), 8000);
    try {
      const r = await fetch(rota + (rota.indexOf('?') < 0 ? '?' : '&') + 't=' + Date.now(), { cache: 'no-store', signal: limite.signal });
      if (r.status === 401) { location.href = '/login'; throw new Error('401'); }
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } finally { clearTimeout(relogio); leiturasNaFila.delete(rota); }
  });
  leiturasNaFila.set(rota, vez);
  filaLeituras = vez.catch(() => { });
  return vez;
}
function conexao(ok) {
  falhas = ok ? 0 : falhas + 1;
  const caiu = falhas >= 2;
  document.body.classList.toggle('desconectado', caiu);
  document.getElementById('estadoLateral').innerHTML = caiu
    ? '<span class="ponto off"></span><span style="color:var(--perigo)">Reconectando…</span>'
    : '<span class="ponto"></span><span style="color:var(--ok)">Hub online</span>';
  if (ok) ultimaAtualizacao = Date.now();
}
function segundosDesde() {
  return ultimaAtualizacao ? 'há ' + Math.round((Date.now() - ultimaAtualizacao) / 1000) + ' s' : '---';
}
document.getElementById('hostLateral').textContent = location.hostname;

let st = null, htmlSt = '', htmlNovos2 = '';
const ha = (s) => s == null ? '---' : s < 60 ? 'há ' + s + ' s' : s < 3600 ? 'há ' + Math.round(s / 60) + ' min' : 'há ' + Math.round(s / 3600) + ' h';
function linha(r, v) { return '<div class="info-wifi"><span>' + r + '</span><span>' + v + '</span></div>'; }
function desenharSt() {
  if (!st) return;
  const h = st.hub;
  document.getElementById('stResumo').innerHTML = [
    ['Ambientes online', h.online + ' de ' + h.total], ['Ligados ao hub', h.ligados + ' de ' + h.slaves],
    ['Zigbee2MQTT', h.zigbee2mqttOnline ? 'no ar' : 'sem resposta'], ['Alarme', h.alarme || '---']
  ].map((x) => '<section class="cartao" style="padding:16px 18px"><span class="rotulo">' + x[0] + '</span><b style="display:block;margin-top:6px;font-size:20px">' + esc(x[1]) + '</b></section>').join('');
  document.getElementById('stQtd').textContent = st.slaves.length + ' ambiente(s)';
  const lista = st.slaves.map((e) => '<section class="cartao"><div class="perfil-topo"><div><h4 style="margin:0">' + esc(e.nome) + '</h4><div class="sub">' +
    (e.viaMaster ? 'ambiente do Master' : 'Slave ' + esc(e.mac.slice(-6))) + '</div></div><span class="selo ' + (e.online ? 'ok' : 'perigo') + '">' + (e.online ? 'Online' : 'Offline') + '</span></div>' +
    linha('IP', esc(e.ip || '---')) + linha('Versão', esc(e.versao ? 'v' + e.versao : '---') + (e.estadoFw ? ' · ' + esc(e.estadoFw) : '')) +
    (e.viaMaster ? '' : linha('Wi-Fi', e.rssi != null ? e.rssi + ' dBm' : '---') + linha('Ligado ao hub', e.ligado ? 'sim (MQTT)' : 'não') + linha('Hub é o dono', e.dono ? 'sim' : 'não')) +
    linha('Radar', e.radar ? (e.presenca ? 'vendo alguém' : 'sala vazia') : 'sem radar') + (e.extras ? linha('Sensores extras', esc(e.extras)) : '') +
    linha('Temperatura', e.temperatura != null ? numero(e.temperatura, 1) + ' °C' : '---') + linha('Último sinal', ha(e.vistoHaSegundos)) +
    (e.viaMaster ? '<div class="rodape-auto" style="margin-top:12px"><button class="btn btn-claro btn-pequeno btn-perigo" type="button" data-esquecer="' + esc(e.mac) + '">Esquecer</button></div>'
      : '<div class="rodape-auto" style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">' +
      '<button class="btn btn-claro btn-pequeno" type="button" data-renomear="' + esc(e.mac) + '">Renomear</button>' +
      (e.ligado ? '<button class="btn btn-claro btn-pequeno" type="button" data-reiniciar="' + esc(e.mac) + '">Reiniciar</button>' : '') +
      '<button class="btn btn-claro btn-pequeno btn-perigo" type="button" data-esquecer="' + esc(e.mac) + '">Esquecer</button></div>') +
    '</section>').join('') || '<div class="cartao"><p class="desc" style="margin:0">Nenhum ainda.</p></div>';
  if (lista !== htmlSt) { htmlSt = lista; document.getElementById('stLista').innerHTML = lista; }
  const novos = st.slaves.filter((e) => !e.viaMaster && e.online && !e.ligado);
  const hn = '<h4>Fora do hub</h4>' + (novos.length ? novos.map((e) => '<div class="zig-item"><div><b>' + esc(e.nome) + '</b><small>' + esc(e.ip) + ' · v' + esc(e.versao || '?') + '</small></div>' +
    '<button class="btn btn-principal btn-pequeno" style="margin:0;width:auto" type="button" data-ligar-hub="' + esc(e.mac) + '"' + (st.hub.temMqttNovos ? '' : ' disabled') + '>Ligar ao hub</button></div>').join('') +
    (st.hub.temMqttNovos ? '' : '<p class="nota" style="font-size:12px;color:var(--texto3)">Salve o usuário do MQTT ao lado para ligar com um clique.</p>')
    : '<p class="desc" style="margin:0">Nenhum: todos os Slaves da rede já estão no hub.</p>');
  if (hn !== htmlNovos2) { htmlNovos2 = hn; document.getElementById('stNovos').innerHTML = hn; }
}
async function atualizarSt() {
  try { st = await buscar('/accontrol/api/status'); document.getElementById('ipLateral').textContent = st.hub.ip || ''; conexao(true); desenharSt(); }
  catch (_) { conexao(false); }
}
async function enviarJson(rota, corpo) {
  const r = await fetch(rota, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(corpo) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || j.ok === false) throw new Error(j.erro || 'Erro HTTP ' + r.status);
  return j;
}
document.getElementById('stLista').addEventListener('click', async (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  const mac = b.dataset.renomear || b.dataset.reiniciar || b.dataset.esquecer, x = st.slaves.find((y) => y.mac === mac);
  try {
    if (b.dataset.renomear) {
      const nome = prompt('Nome do ambiente', x.nome);
      if (nome == null) return;
      await enviarJson('/accontrol/api/nome', { mac, nome }); aviso('Nome salvo ✓');
    } else if (b.dataset.reiniciar) {
      if (!confirm('Reiniciar o Slave de ' + x.nome + '?')) return;
      await enviarJson('/accontrol/api/admin', { mac, acao: 'reiniciar' }); aviso('Reiniciando…');
    } else if (b.dataset.esquecer) {
      if (!confirm('Esquecer ' + x.nome + '? Ele some do painel; se continuar ligado, volta a aparecer.')) return;
      await enviarJson('/accontrol/api/esquecer', { mac }); aviso('Esquecido');
    }
