});
document.getElementById('stNovos').addEventListener('click', async (e) => {
  const b = e.target.closest('[data-ligar-hub]');
  if (!b) return;
  b.disabled = true;
  try { await enviarJson('/accontrol/api/ligar-ao-hub', { mac: b.dataset.ligarHub }); aviso('Ligado ao hub ✓ Em alguns segundos ele aparece como ligado.'); }
  catch (err) { aviso(err.message, true); b.disabled = false; }
  setTimeout(() => { htmlNovos2 = ''; atualizarSt(); }, 5000);
