  if (!dados || dados.tipo !== 'accontrol-backup') { t.className = 'retorno erro'; t.textContent = 'Este arquivo não é um backup do hub.'; return; }
  if (!confirm('Restaurar o backup de ' + (dados.criadoEm || '?') + '? O que está no hub agora (nomes, alarme, luzes, Telegram, histórico) é substituído.')) return;
  try { const j = await enviarJson('/accontrol/api/restaurar', dados); t.className = 'retorno ok'; t.textContent = 'Restaurado ✓ (' + j.arquivos + ' arquivo(s) do histórico).'; htmlSt = ''; atualizarSt(); }
  catch (err) { t.className = 'retorno erro'; t.textContent = err.message; }
});
atualizarSt();
setInterval(atualizarSt, 4000);
