function getMe(t) { return t.token ? { method: 'GET', requestTimeout: 15000, url: 'https://api.telegram.org/bot' + t.token + '/getMe' } : null; }

// GET /seguranca/telegram: o formato do Master (telegram_alarme.cpp).
const t = cfgTg();
msg.payload = { token: !!t.token, bot: t.bot || '', erro: t.erro || '',
  link: t.bot ? 'https://t.me/' + t.bot + '?start=' + t.codigo : '',
  contatos: t.chats.map((c) => ({ id: String(c.id), nome: c.nome })) };
msg.headers = { 'cache-control': 'no-store' };
return [msg, null, null, null];

const LETRAS = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
function novoCodigo() { let c = ''; for (let i = 0; i < 12; i++) c += LETRAS[Math.floor(Math.random() * LETRAS.length)]; return c; }
function cfgTg() { return flow.get('tgHub') || { token: '', bot: '', codigo: novoCodigo(), chats: [], erro: '' }; }
function publicar(t) { return { topic: 'accontrol/hub/telegram/config', payload: { token: t.token, chats: t.chats.map((c) => ({ id: c.id, nome: c.nome })) } }; }
function gravar(t) { return { payload: JSON.stringify(t) }; }
function getMe(t) { return t.token ? { method: 'GET', requestTimeout: 15000, url: 'https://api.telegram.org/bot' + t.token + '/getMe' } : null; }

// POST /seguranca/telegram/token | /codigo | /remover (as rotas do Master).
const q = msg.req.query || {};
const t = cfgTg();
const erro = (x) => { msg.statusCode = 400; msg.payload = { ok: false, erro: x }; return [msg, null, null, null]; };
let checar = null;
if (msg.req.path.endsWith('/token')) {
  const novo = String(q.token || '').trim();
  if (novo && !/^\d{5,}:[A-Za-z0-9_-]{30,}$/.test(novo)) return erro('Token inválido: copie a linha inteira que o @BotFather mandou');
  t.token = novo; t.bot = ''; t.erro = ''; t.chats = []; t.codigo = novoCodigo();
  checar = getMe(t);
} else if (msg.req.path.endsWith('/codigo')) t.codigo = novoCodigo();
else if (msg.req.path.endsWith('/remover')) t.chats = t.chats.filter((c) => String(c.id) !== String(q.id));
flow.set('tgHub', t);
msg.payload = { ok: true };
return [msg, gravar(t), publicar(t), checar];

