function cfgTg() { return flow.get('tgHub') || { token: '', bot: '', codigo: novoCodigo(), chats: [], erro: '' }; }
function publicar(t) { return { topic: 'accontrol/hub/telegram/config', payload: { token: t.token, chats: t.chats.map((c) => ({ id: c.id, nome: c.nome })) } }; }
function gravar(t) { return { payload: JSON.stringify(t) }; }
