// accontrol/+/telegram/config (de um Master: cópia na primeira vez; depois o hub manda)
// e accontrol/hub/telegram/cadastro (alguém leu o QR e tocou em Iniciar).
const p = msg.topic.split('/');
const t = cfgTg();
if (p[3] === 'config') {
  if (p[1] === 'hub') return null;
  const c = msg.payload || {};
  if (!t.token && c.token) {               // primeira vez: o hub assume o bot e as pessoas do Master
    t.token = c.token; t.chats = (c.chats || []).slice(0, 10); t.codigo = t.codigo || novoCodigo();
    flow.set('tgHub', t);
    return [null, gravar(t), publicar(t), getMe(t)];
  }
  if (t.token && JSON.stringify(publicar(t).payload) !== JSON.stringify({ token: c.token, chats: c.chats })) return [null, null, publicar(t), null];
  return null;
}
if (p[1] !== 'hub' || p[3] !== 'cadastro') return null;
const c = msg.payload || {};
const chat = Number(c.chat);
if (!chat || !t.token || String(c.codigo) !== t.codigo) return null;   // código de outro lugar ou vencido: o fluxo avisa a pessoa
const nome = String(c.nome || 'sem nome').replace(/[;:"\\]/g, '').trim().slice(0, 30) || 'sem nome';
const resposta = (ok, e) => ({ topic: 'accontrol/hub/telegram/resposta', payload: ok ? { chat, ok: true } : { chat, ok: false, erro: e } });
const i = t.chats.findIndex((x) => Number(x.id) === chat);
if (i < 0 && t.chats.length >= 10) return [null, null, resposta(false, 'limite de 10 pessoas'), null];
if (i < 0) t.chats.push({ id: chat, nome }); else t.chats[i].nome = nome;
flow.set('tgHub', t);
return [null, gravar(t), [publicar(t), resposta(true)], null];

