// getMe: o nome do bot vai no link do QR.
const t = cfgTg();
const r = msg.payload || {};
if (msg.error || !r.ok) { t.erro = msg.statusCode === 401 || /401/.test(String(msg.error && msg.error.message)) ? 'token recusado pelo Telegram' : 'sem conexão com o Telegram'; }
else { t.bot = r.result.username; t.erro = ''; }
flow.set('tgHub', t);
return gravar(t);

