// Ao iniciar e a cada 5 min: lê o arquivo (só na 1ª vez) e republica a configuração
// (o fluxo do Telegram guarda só na memória e perde ao reiniciar).
// Sem bot ainda: pede ao Master a configuração dele (o hub copia na primeira vez).
function pedirAoMaster() {
  const slaves = flow.get('slaves') || {};
  return Object.values(slaves).filter((s) => s.viaMaster).map((s) => ({ topic: s.viaMaster.topico.split('/').slice(0, 2).join('/') + '/telegram/pedir', payload: '1' }));
}
if (msg.topic === 'arquivo') {
  try { const t = JSON.parse(msg.payload || ''); if (t && typeof t === 'object') flow.set('tgHub', t); } catch (e) { }
  const t = cfgTg();
  return [null, t.token ? publicar(t) : pedirAoMaster(), t.token && !t.bot ? getMe(t) : null];
}
const t = cfgTg();
return [null, t.token ? publicar(t) : pedirAoMaster(), null];

// GET /accontrol/api/feriados
const cfg = flow.get('segCfg') || {"feriadosLocais": [], "habilitada": true, "modoTeste": true, "minutos": 15, "segundos": 3, "feriadoFechado": true, "ignorados": [], "dias": [{"funciona": false, "abre": 480, "fecha": 1080}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": true, "abre": 330, "fecha": 1140}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": false, "abre": 480, "fecha": 1080}]};
const lista = cfg.feriadosLocais || [];
const desejada = lista.map((f) => f.data).join(',');
const slaves = flow.get('slaves') || {}, nomes = flow.get('nomes') || {};
const ambientes = Object.keys(slaves).filter((m) => !slaves[m].viaMaster).map((m) => {
  const s = slaves[m], b = s.bruto || {};
  return { nome: nomes[m] || (s.estado || {}).nome || b.nome || m, online: !!s.online,
           suporta: typeof b.feriadosLocais === 'string', ok: b.feriadosLocais === desejada };
}).sort((x, y) => x.nome.localeCompare(y.nome));
msg.payload = { lista, ambientes };
msg.headers = { 'cache-control': 'no-store' };
return msg;

// POST /accontrol/api/feriados {lista: [{data, nome}]}
const erro = (t) => { msg.statusCode = 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
const entrada = (msg.payload && msg.payload.lista) || [];
if (!Array.isArray(entrada) || entrada.length > 30) return erro('No máximo 30 feriados locais');
const lista = [], vistos = {};
for (const f of entrada) {
  const data = String((f && f.data) || '').trim(), nome = String((f && f.nome) || '').trim().slice(0, 40);
  const m = data.match(/^(\d\d)\/(\d\d)(?:\/(\d{4}))?$/);
  if (!m) return erro('Data inválida: ' + data);
  const dia = +m[1], mes = +m[2], ano = m[3] ? +m[3] : 2024;
  if (dia < 1 || dia > 31 || mes < 1 || mes > 12 || ano < 2024 || ano > 2099) return erro('Data inválida: ' + data);
  if (vistos[data]) continue;
  vistos[data] = true;
  lista.push({ data, nome });
}
const chave = (f) => f.data.slice(3, 5) + f.data.slice(0, 2) + (f.data.slice(6) || '0000');
lista.sort((x, y) => chave(x).localeCompare(chave(y)));
const cfg = Object.assign({}, flow.get('segCfg') || {"feriadosLocais": [], "habilitada": true, "modoTeste": true, "minutos": 15, "segundos": 3, "feriadoFechado": true, "ignorados": [], "dias": [{"funciona": false, "abre": 480, "fecha": 1080}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": true, "abre": 330, "fecha": 1140}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": true, "abre": 390, "fecha": 1140}, {"funciona": false, "abre": 480, "fecha": 1080}]}, { feriadosLocais: lista });
flow.set('segCfg', cfg);
flow.set('feriadosEnviados', {});  // manda já aos Slaves, no próximo anúncio de cada um
msg.payload = { ok: true, lista };
return [{ payload: JSON.stringify(cfg, null, 2) }, msg];
